// ─── File: SameFileDemo.java ───
// Sealed interface AND all its permitted subtypes live in THIS single file,
// so the `permits` clause is OPTIONAL — the compiler infers the set.
package com.bank.samefile;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.*;

public class SameFileDemo {
    private static final Logger log = Logger.getLogger(SameFileDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ResultHandler handler = new ResultHandler();
        List<TransactionResult> results = List.of(
            new Approved("TXF-1", new BigDecimal("50000")),
            new Declined("TXF-2", "Insufficient funds"),
            new Pending("TXF-3", "Awaiting OTP"));

        for (TransactionResult r : results) {
            log.info(() -> handler.describe(r));
        }
    }
}

// ─── Sealed interface with NO `permits` clause ───
// Because Approved, Declined, Pending are declared in THIS SAME FILE, the
// compiler infers the permitted set to be exactly those three.
sealed interface TransactionResult { String reference(); }

// Records are implicitly final → satisfy the final/sealed/non-sealed rule.
record Approved(String reference, BigDecimal amount) implements TransactionResult { }
record Declined(String reference, String reason)     implements TransactionResult { }
record Pending(String reference, String note)        implements TransactionResult { }

// If, say, Pending moved to its own file Pending.java, then TransactionResult
// WOULD need an explicit clause:
//   sealed interface TransactionResult permits Approved, Declined, Pending { ... }

// ─── Exhaustive handling over the inferred sealed set (no default needed) ───
class ResultHandler {
    String describe(TransactionResult r) {
        return switch (r) {
            case Approved a -> "APPROVED " + a.reference() + " amount Rs." + a.amount();
            case Declined d -> "DECLINED " + d.reference() + " reason=" + d.reason();
            case Pending p  -> "PENDING  " + p.reference() + " note=" + p.note();
        };
    }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override public String format(java.util.logging.LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
